const raw = $input.first().json;

let text;
try {
  const sc = raw.structuredContent;
  if (sc && Array.isArray(sc.itineraries) && sc.itineraries.length > 0) {
    const currency = sc.currency || '';
    const top = sc.itineraries.slice(0, 3);
    const lines = top.map((it, i) => {
      const out = it.outbound;
      const inb = it.inbound;
      const outDesc = out ? `去程 ${(out.departureTime || '').slice(0, 10)} ${out.from}→${out.to} ${out.stops > 0 ? `轉機${out.stops}次` : '直飛'}` : '';
      const inDesc = inb ? `回程 ${(inb.departureTime || '').slice(0, 10)} ${inb.from}→${inb.to} ${inb.stops > 0 ? `轉機${inb.stops}次` : '直飛'}` : '';
      return `${i + 1}. ${it.priceFormatted || (it.price + ' ' + currency)}｜${outDesc}${inDesc ? '；' + inDesc : ''}
訂票：${it.bookingUrl || ''}`;
    });
    text = `查到${sc.resultsCount || top.length}筆航班，幣別${currency}，以下為精選前${top.length}筆：\n\n` + lines.join('\n\n');
  } else if (typeof raw === 'string') {
    text = raw;
  } else {
    text = JSON.stringify(raw).slice(0, 1500);
  }
} catch (e) {
  text = '機票查詢失敗，請稍後再試。';
}

return [{ json: { output: text } }];
